import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { launchRenderBrowser } from "/Users/jjae/.codex/worktrees/pr44-review/still-shift/packages/execution-runtime/src/render-browser.ts";
import { createProgramPreview } from "/Users/jjae/.codex/worktrees/pr44-review/still-shift/tools/still-shift-cli/src/composition/preview.ts";

const root = await mkdtemp(join(tmpdir(), "pr44-focus-"));
const input = join(root, "source.json");
const art = Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4"><rect width="4" height="4" fill="red"/></svg>');
await writeFile(join(root, "art.svg"), art);
await writeFile(input, JSON.stringify({
  schemaVersion: "composition-1", id: "focus", width: 64, height: 64,
  fps: 24, frameCount: 8,
  assets: [{ id: "art", type: "image", path: "art.svg", width: 4, height: 4,
    sha256: `sha256:${createHash("sha256").update(art).digest("hex")}` }],
  layers: [{ id: "box", type: "image", size: [16, 16], threeD: true,
    sources: [{ asset: "art" }], transform: { position: [32, 32, 0] } }],
}));
let app: Awaited<ReturnType<typeof createProgramPreview>> | undefined;
let browser: Awaited<ReturnType<typeof launchRenderBrowser>> | undefined;
try {
  app = await createProgramPreview(input, { watch: false });
  browser = await launchRenderBrowser();
  const page = await browser.newPage();
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto(app.url);
  await page.waitForFunction(() => Number(document.getElementById("status")?.dataset.revision) > 0);
  const ready = () => page.waitForFunction(() =>
    !document.querySelector<HTMLFieldSetElement>("#inspector-edit")!.disabled);
  const active = () => page.evaluate(() => ({
    tag: document.activeElement?.tagName,
    id: document.activeElement?.id,
    text: document.activeElement?.textContent?.trim().slice(0, 100),
    layerControl: (document.activeElement as HTMLElement)?.dataset.layerControl,
  }));
  const row = page.locator('[data-layer="box"]');
  const select = row.locator('button').first();
  await select.focus();
  await select.press("Space");
  await ready();
  const selectResult = await active();
  assert.equal(await select.evaluate((node) => document.activeElement === node), true, "existing select baseline");
  const hide = row.getByRole("button", { name: "Hide", exact: true });
  await hide.focus();
  await hide.press("Space");
  await row.getByRole("button", { name: "Show", exact: true }).waitFor();
  const hideResult = await active();
  assert.equal(await row.getByRole("button", { name: "Show", exact: true }).evaluate((node) => document.activeElement === node), true, "existing Hide baseline");
  await row.getByRole("button", { name: "Show", exact: true }).press("Space");
  await row.getByRole("button", { name: "Hide", exact: true }).waitFor();
  const receiving = row.locator('[data-control="receives-light"]');
  await receiving.focus();
  await receiving.press("Space");
  await page.waitForFunction(() => document.querySelector('[data-control="receives-light"]')?.getAttribute("aria-pressed") === "true");
  await ready();
  const receiveResult = await active();
  const receivePreserved = await receiving.evaluate((node) => document.activeElement === node);
  let resumeAsset!: () => void;
  const pausedAsset = new Promise<void>((resolve) => { resumeAsset = resolve; });
  const requested = page.waitForRequest(/composition\/program-asset\?/, { timeout: 15000 });
  await page.route("**/composition/program-asset?*", async (route) => {
    await pausedAsset;
    await route.continue();
  });
  await receiving.focus();
  await receiving.press("Space");
  await requested;
  await page.locator("#overlay-safe").focus();
  resumeAsset();
  await page.waitForFunction(() => document.querySelector('[data-control="receives-light"]')?.getAttribute("aria-pressed") === "false");
  await ready();
  const movedFocusResult = await active();
  const movedFocusPreserved = await page.locator("#overlay-safe").evaluate((node) => document.activeElement === node);
  assert.deepEqual(errors, []);
  console.log(JSON.stringify({
    selectResult, hideResult, receiveResult, receivePreserved,
    movedFocusResult, movedFocusPreserved, errors,
  }, null, 2));
} finally {
  await browser?.close();
  await app?.close();
  await rm(root, { recursive: true, force: true });
}

