import { evaluateComp, evaluateStageProperty } from '/Users/jjae/.codex/worktrees/pr44-review/still-shift/packages/renderer-core/src/composition/evaluate/index.ts';
import { validateComposition, type Composition, type CompositionLayer } from '/Users/jjae/.codex/worktrees/pr44-review/still-shift/packages/scene-contract/src/index.ts';

const base = { schemaVersion: 'composition-1' as const, id: 'main', width: 100, height: 100, fps: 24, frameCount: 24, assets: [] };
const results = [];
for (const explicitThreeD of [false, true]) for (const observerFirst of [true, false]) {
  const light: CompositionLayer = { id: 'light', type: 'light', lightType: 'point', ...(explicitThreeD ? { threeD: true } : {}) };
  const observer: CompositionLayer = { id: 'plane', type: 'solid', size: [20, 20], color: '#ffffff', threeD: true, receivesLight: true, transform: { position: [50, 50, 0] } };
  const doc: Composition = { ...base, layers: observerFirst ? [observer, light] : [light, observer], expressions: { 'light.transform.anchor.z': { source: '20' }, 'plane.transform.position.z': { source: "ref('light.constraintReference.z')" } } };
  const tree = evaluateComp(doc, 5);
  results.push({ explicitThreeD, observerFirst, planeZ: tree.layers.find(state => state.id === 'plane')!.transform.position[2], lightWorldZ: tree.lights![0]!.position[2], referenceZInFreshStage: evaluateStageProperty(doc, 'light.constraintReference.z', 5).value });
}
const cycles = [false, true].map(explicitThreeD => {
  const doc: Composition = { ...base, layers: [{ id: 'light', type: 'light', lightType: 'point', ...(explicitThreeD ? { threeD: true } : {}) }], expressions: { 'light.transform.anchor.z': { source: "ref('light.constraintReference.z') + 20" } } };
  const validation = validateComposition(doc);
  return { explicitThreeD, ok: validation.ok, diagnostics: validation.diagnostics.map(diagnostic => ({ code: diagnostic.code, message: diagnostic.message })) };
});
console.log(JSON.stringify({ results, cycles }, null, 2));
